export function installPanelResizers(onChange){const main=document.querySelector('main'),root=document.documentElement;const defaults={rail:58,library:274,inspector:294,timeline:220,palette:150,workspaceHeight:540,libraryHeight:460,inspectorHeight:680};let preferred={...defaults};try{Object.assign(preferred,JSON.parse(localStorage.getItem('afterimage-layout-v13')||'{}'))}catch{}const values={...preferred},min={rail:48,library:180,inspector:220,timeline:100,palette:85,workspaceHeight:320,libraryHeight:220,inspectorHeight:350},max={rail:110,library:650,inspector:650,timeline:600,palette:400,workspaceHeight:1200,libraryHeight:1200,inspectorHeight:1400};
 function layout(){const w=main.clientWidth;for(const k of Object.keys(values))values[k]=Math.max(min[k],Math.min(max[k],Number(preferred[k])||defaults[k]));if(w>860){let excess=values.rail+values.library+values.inspector+240-w;if(excess>0){const room=values.library-min.library+values.inspector-min.inspector;const fraction=Math.min(1,excess/Math.max(1,room));values.library-=(values.library-min.library)*fraction;values.inspector-=(values.inspector-min.inspector)*fraction;}}values.timeline=Math.min(values.timeline,Math.max(100,main.clientHeight-210));values.palette=Math.min(values.palette,Math.max(85,main.clientHeight*.4));for(const [k,v]of Object.entries(values))root.style.setProperty('--'+k+'-size',v+'px');onChange();}
 function persist(){localStorage.setItem('afterimage-layout-v13',JSON.stringify(preferred));}
 function add(key,parent,orientation,sign=1,extra=''){const handle=document.createElement('div');handle.className='panel-splitter splitter-'+key+' '+extra;handle.tabIndex=0;handle.setAttribute('role','separator');handle.setAttribute('aria-label',({rail:'工具栏宽度',library:'素材栏宽度',inspector:'检查器宽度',timeline:'时间轴高度',palette:'调色板高度',workspaceHeight:'画布区高度',libraryHeight:'素材区高度',inspectorHeight:'检查器高度'})[key]);handle.title=handle.getAttribute('aria-label')+' · 拖动调整 / 双击恢复 / 方向键微调';handle.setAttribute('aria-orientation',orientation);handle.setAttribute('aria-valuemin',min[key]);handle.setAttribute('aria-valuemax',max[key]);parent.append(handle);let gesture=null;handle.onpointerdown=e=>{e.preventDefault();gesture={at:orientation==='vertical'?e.clientX:e.clientY,start:values[key]};handle.setPointerCapture(e.pointerId);document.body.classList.add('resizing-panel');};handle.onpointermove=e=>{if(!gesture)return;preferred[key]=Math.max(min[key],Math.min(max[key],gesture.start+((orientation==='vertical'?e.clientX:e.clientY)-gesture.at)*(key==='library'&&document.body.dataset.layout==='right'?-sign:sign)));layout();handle.setAttribute('aria-valuenow',Math.round(values[key]));};const finish=()=>{gesture=null;document.body.classList.remove('resizing-panel');persist();};handle.onpointerup=finish;handle.onpointercancel=finish;handle.ondblclick=()=>{preferred[key]=defaults[key];layout();persist();};handle.onkeydown=e=>{const keys=orientation==='vertical'?['ArrowLeft','ArrowRight']:['ArrowUp','ArrowDown'];if(!keys.includes(e.key))return;e.preventDefault();e.stopPropagation();preferred[key]=values[key]+(e.key===keys[1]?1:-1)*sign*(e.shiftKey?40:10);layout();persist();handle.setAttribute('aria-valuenow',Math.round(values[key]));};return handle;}
 add('rail',main,'vertical');add('library',main,'vertical');add('inspector',main,'vertical',-1);add('timeline',document.querySelector('#timelinePanel'),'horizontal',-1);add('palette',document.querySelector('.palette-panel'),'horizontal',-1);
 add('workspaceHeight',document.querySelector('.workspace'),'horizontal',1,'mobile-height-splitter');add('libraryHeight',document.querySelector('.library'),'horizontal',1,'mobile-height-splitter');add('inspectorHeight',document.querySelector('.inspector'),'horizontal',1,'mobile-height-splitter');
 const observer=new ResizeObserver(layout);observer.observe(main);layout();return {reset(){preferred={...defaults};layout();persist();},values:()=>({...values})};}
